   3	/**
   4	 * A key face as SVG.
   5	 *
   6	 * SVG, because it needs no rasterizer and no native module in a package
   7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
   8	 * rejects a raw SVG string despite the documentation. 144 square is the
   9	 * @2x size; the software scales it to any key.
  10	 *
  11	 * The palette is the app's own: celadon for a key that moves the run,
  12	 * kiln for a refusal and for undo, the muted ink for a key with nothing
  13	 * to do. System sans, since a font in an SVG would have to travel as
  14	 * base64 on every redraw.
  15	 *
  16	 * `stroke` is the frame's width, and `quiet` the color of the `when` line
  17	 * and the corner glyph where the edge is too dark to read them in - which
  18	 * is a readout, whose frame is a hairline rather than an accent.
  19	 */
  20	const TONE: Record<Tone, { ground: string; ink: string; edge: string; stroke?: number; quiet?: string }> = {
  21	  live: { ground: "#1e2f27", ink: "#e7eae6", edge: "#8cc3a6" },
  22	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733" },
  23	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
  24	  undo: { ground: "#1e2f27", ink: "#e7eae6", edge: "#dd8f63" },
  25	  deck: { ground: "#1b201d", ink: "#e7eae6", edge: "#2f3733", quiet: "#8d958f" },
  26	  readout: { ground: "#151311", ink: "#e7eae6", edge: "#2f3733", stroke: 1, quiet: "#8d958f" },
  27	};
  28	
  29	const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  30	
  31	/**
  32	 * Glyph widths in em for the system sans at weight 600 - Segoe UI Semibold
  33	 * on Windows, and near enough everywhere else. Counting characters was
  34	 * pessimistic: "connected" is nine narrow letters and fits at 26, but a
  35	 * count of ten sends it to 22. So the face measures instead, in classes
  36	 * coarse enough to read and close enough that the rendered ink stays
  37	 * inside the frame.
  38	 */
  39	const EM: Record<string, number> = {};
  40	for (const c of "ijl'.,:;!| ") EM[c] = 0.28;
  41	for (const c of "ftrI") EM[c] = 0.36;
  42	for (const c of "mw") EM[c] = 0.85;
  43	for (const c of "MW") EM[c] = 0.92;
  44	EM["…"] = 0.9;
  45	
  46	function em(ch: string): number {
  47	  const known = EM[ch];
  48	  if (known !== undefined) return known;
  49	  if (/[0-9a-z]/.test(ch)) return 0.55;
  50	  if (/[A-Z]/.test(ch)) return 0.68;
  51	  return 0.6;
  52	}
  53	
  54	/** How wide a line of text draws, in px, at this font size. */
  55	export function measure(text: string, size: number): number {
  56	  let w = 0;
  57	  for (const ch of text) w += em(ch);
  58	  return w * size;
  59	}
  60	
  61	/**
  62	 * The frame's usable width. 144 less 8 either side: the stroke is 3px wide
  63	 * centered at x=3, so 8 leaves 5px of clear ground inside it. Text is
  64	 * centered on 72, so a line no wider than this never reaches x=8 or x=136.
  65	 */
  66	const LINE = 144 - 2 * 8;
  67	const MAX_LINES = 3;
  68	
  69	/**
  70	 * The `when` line's own type: 16px monospace, a flat 0.6em per glyph rather
  71	 * than the title's per-glyph measurement. 128px at 16px holds 13 characters
  72	 * (128 / (16 * 0.6) = 13.33); a fourteenth never fits. 18px held only
  73	 * eleven, which cut "press Connect" - the one instruction on the key that
  74	 * has to be read whole - down to "press Conne…".
  75	 */
  76	const WHEN_SIZE = 16;
  77	const WHEN_MAX = 13;
  78	
  79	/**
  80	 * Fit `when` to `WHEN_MAX` characters. A word boundary that still leaves at
  81	 * least six characters reads better than a stub, so that is tried first;
  82	 * otherwise the cut falls back to characters. Either way an "…" marks what
  83	 * was cut, and nothing kept ever runs past `WHEN_MAX`.
  84	 */
  85	function ellipsizeWhen(text: string): string {
  86	  if (text.length <= WHEN_MAX) return text;
  87	  let cut = "";
  88	  for (const word of text.split(" ")) {
  89	    const next = cut ? `${cut} ${word}` : word;
  90	    if (next.length > WHEN_MAX) break;
  91	    cut = next;
  92	  }
  93	  if (cut.length < 6) cut = text.slice(0, WHEN_MAX);
  94	  return `${cut}…`;
  95	}
  96	
  97	/**
  98	 * Greedy word wrap by measured width: pack words onto a line up to `width`
  99	 * px at `size`, at most `lines` lines. A word too wide for a line of its
 100	 * own is broken by characters and carries on below. The last line gets an
 101	 * ellipsis if any text was left over.
 102	 */
 103	/**
 104	 * The longest head of a hyphenated word that still fits, hyphen included,
 105	 * or nothing where the word has no hyphen with anything in front of it.
 106	 */
