 108	  let cut = "";
 109	  for (let i = 1; i < word.length - 1; i++) {
 110	    if (word[i] !== "-") continue;
 111	    const head = word.slice(0, i + 1);
 112	    if (measure(head, size) > width) break;
 113	    cut = head;
 114	  }
 115	  return cut;
 116	}
