 118	export function wrap(text: string, size: number, width = LINE, lines = MAX_LINES): string[] {
 119	  const words = text.split(/\s+/).filter(Boolean);
 120	  const out: string[] = [];
 121	  let i = 0;
 122	  while (i < words.length && out.length < lines) {
 123	    const word = words[i]!;
 124	    if (measure(word, size) > width) {
 125	      // A hyphen is already a break somebody wrote into the word, so it is
 126	      // the one to use: "Bare-handed" reads as "Bare-" and "handed", not
 127	      // as "Bare-hande" and "d". The hyphen stays on the line it ends.
 128	      let cut = hyphenated(word, size, width);
 129	      if (cut === "") {
 130	        for (const ch of word) {
 131	          if (measure(cut + ch, size) > width) break;
 132	          cut += ch;
 133	        }
 134	      }
 135	      // One glyph always goes, or a face narrower than its own type would
 136	      // loop here forever.
 137	      if (cut === "") cut = [...word][0]!;
 138	      out.push(cut);
 139	      words[i] = word.slice(cut.length);
 140	      continue;
 141	    }
 142	    let line = word;
 143	    i++;
 144	    while (i < words.length && measure(line + " " + words[i], size) <= width) {
 145	      line += " " + words[i];
 146	      i++;
 147	    }
 148	    out.push(line);
 149	  }
 150	  if (i < words.length && out.length > 0) {
 151	    let last = out[out.length - 1]!;
 152	    while (last.length > 0 && measure(last + "…", size) > width) last = last.slice(0, -1);
 153	    out[out.length - 1] = last + "…";
 154	  }
 155	  return out;
 156	}
