 158	/**
 159	 * The type scale, biggest first. Every step gets the same three lines and
 160	 * the same 128px; what changes is how much of a phrase that holds. A title
 161	 * takes the first step that keeps every word whole; one too long for the
 162	 * last step is wrapped to it anyway and ellipsized rather than drawn over
 163	 * the frame.
 164	 */
 165	const SCALE = [40, 34, 30, 26, 22] as const;
 166	
 167	/** Whether wrapping at this size keeps every word of the phrase. */
 168	function whole(text: string, size: number): boolean {
 169	  return wrap(text, size).join(" ") === text.split(/\s+/).filter(Boolean).join(" ");
 170	}
 171	
 172	function typeset(text: string): { lines: string[]; size: number } {
 173	  const size = SCALE.find((s) => whole(text, s)) ?? SCALE[SCALE.length - 1]!;
 174	  return { lines: wrap(text, size), size };
 175	}
 176	
 177	/**
 178	 * The corner glyph: 18px square, 8px in from the top and the left.
 179	 *
 180	 * The action's own drawing, so a key says which key it is while the title
 181	 * says what it would do. The drawings are 144 square (`design/actions`),
 182	 * so the scale is 18/144; they are drawn in white, and the white is
 183	 * swapped for the tone's quiet color the way `design/export.mjs` swaps it
 184	 * for the key images. 70% opacity keeps it a mark rather than a second
 185	 * thing to read - the title is the thing to read.
 186	 */
 187	const GLYPH_PX = 18;
 188	const GLYPH_AT = 8;
 189	
 190	function corner(glyph: string, color: string): string {
 191	  const scale = (GLYPH_PX / 144).toFixed(5);
 192	  return `<g transform="translate(${GLYPH_AT} ${GLYPH_AT}) scale(${scale})" opacity="0.7">${glyph.replaceAll("#ffffff", color)}</g>`;
 193	}
