 195	export function faceImage(face: Face, glyph?: string): string {
 196	  const t = TONE[face.tone];
 197	  const quiet = t.quiet ?? t.edge;
 198	  const { lines, size } = typeset(face.title);
 199	  const top = 72 - ((lines.length - 1) * size * 1.15) / 2 + (face.when ? -10 : 0);
 200	  // One positioned <text> per line, baseline given outright: the software
 201	  // draws SVG with a renderer that honors x and y on a text element and
 202	  // little else - a tspan with its own position, or a dominant-baseline,
 203	  // left every title off the key while the small line beneath it showed.
 204	  // 0.36em is where the middle of a semibold sans sits above its baseline.
 205	  const spans = lines
 206	    .map(
 207	      (l, i) =>
 208	        `<text class="t" x="72" y="${(top + i * size * 1.15 + size * 0.36).toFixed(1)}" text-anchor="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="Segoe UI, Helvetica Neue, Helvetica, Arial, sans-serif">${esc(l)}</text>`,
 209	    )
 210	    .join("");
 211	  const when = face.when
 212	    ? `<text x="72" y="126" text-anchor="middle" font-size="${WHEN_SIZE}" fill="${quiet}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(ellipsizeWhen(face.when))}</text>`
 213	    : "";
 214	  const svg =
 215	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
 216	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
 217	    // thing even when the drawn lines above cut it short.
 218	    `<title>${esc(face.title)}</title>` +
 219	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
 220	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="${t.stroke ?? 3}"/>` +
 221	    (glyph ? corner(glyph, quiet) : "") +
 222	    spans +
 223	    when +
 224	    `</svg>`;
 225	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
 226	}

