  4	/** The lines a face draws, with the size it drew them at. */
  5	function drawn(title: string): { lines: string[]; size: number } {
  6	  const svg = Buffer.from(faceImage({ title, tone: "live" }).split(",")[1]!, "base64").toString("utf8");
  7	  return {
  8	    lines: [...svg.matchAll(/<text class="t"[^>]*>([^<]*)<[/]text>/g)].map((m) => m[1]!),
  9	    size: Number(/font-size="(\d+)" font-weight/.exec(svg)![1]),
 10	  };
 11	}
