 13	/** The `when` line a face draws, with the font size it drew it at. */
 14	function whenLine(when: string): { text: string; size: number } {
 15	  const svg = Buffer.from(faceImage({ title: "Weather", tone: "live", when }).split(",")[1]!, "base64").toString("utf8");
 16	  const m = /<text x="72" y="126"[^>]*font-size="(\d+)"[^>]*>([^<]*)<\/text>/.exec(svg)!;
 17	  return { size: Number(m[1]), text: m[2]! };
